import{_ as e,o as a,c as l,a4 as i}from"./chunks/framework.2-Vke5-n.js";const r="/arch-guidelines/assets/dama.BahXCPgS.png",g=JSON.parse('{"title":"","description":"","frontmatter":{"sidebarDepth":4,"author":"フューチャー株式会社","layout":"home","hero":{"name":"データマネジメント<wbr>設計ガイドライン","tagline":"Data Management Design Guidelines","actions":[{"theme":"brand","text":"データマネジメント設計ガイドライン","link":"./datamanagement_guidelines.md"}]}},"headers":[],"relativePath":"documents/forDataManagement/index.md","filePath":"documents/forDataManagement/index.md"}'),n={name:"documents/forDataManagement/index.md"};function d(s,t,o,h,c,p){return a(),l("div",null,[...t[0]||(t[0]=[i('<h2 id="はじめに" tabindex="-1">はじめに <a class="header-anchor" href="#はじめに" aria-label="Permalink to &quot;はじめに&quot;">​</a></h2><p>データマネジメントは、適切なデータ利活用を促進するための活動である。</p><p>データは様々な業務やシステムから生成され、その出力先や形式も様々である。情報流出などセキュリティ対応のため、権限を持った社員のみアクセス可能とすることが鉄則であるが、必要以上に権限を絞り過ぎると組織内のデータ流通が阻害され、競争力低下の懸念がある。一方で適切な権限設定を個々人の判断に委ねることが難しいのも実情である。そのため、組織のデータリテラシーやデータ利活用の成熟度に合わせて適切な方針や仕組みが求められており、昨今の生成AIブームでその重要性はさらに増している。</p><p>本ガイドラインはデータマネジメントの設計における主要な論点や方針をまとめる。それによりデータマネジメント設計者が悩むポイントを軽減し、同時に議論のベースラインを提供する。本ガイドラインがデータマネジメント担当者やデータ基盤を構築するデータエンジニアの道標となれば幸いである。</p><div class="warning custom-block"><p class="custom-block-title">免責事項</p><ul><li>有志で作成したドキュメントである。フューチャーには多様なプロジェクトが存在し、それぞれの状況に合わせて工夫された開発プロセスや高度な開発支援環境が存在する。本ガイドラインはフューチャーの全ての部署 / プロジェクトで適用されているわけではなく、有志が観点を持ち寄って新たに整理したものである</li><li>相容れない部分があればその領域を書き換えて利用することを想定している。プロジェクト固有の背景や要件への配慮は、ガイドライン利用者が最終的に判断すること。本ガイドラインに必ず従うことは求めておらず、設計案の提示と、それらの評価観点を利用者に提供することを主目的としている</li><li>掲載内容および利用に際して発生した問題、それに伴う損害については、フューチャー株式会社は一切の責務を負わないものとする。掲載している情報は予告なく変更する場合がある</li></ul></div><h2 id="前提条件" tabindex="-1">前提条件 <a class="header-anchor" href="#前提条件" aria-label="Permalink to &quot;前提条件&quot;">​</a></h2><p>基本的なアクセス管理ポリシーなど、何かしらのセキュリティポリシーは存在するが、データマネジメントに特化したポリシーの策定や運用が始まったばかりの組織を前提とし、組織で利用する統一的なデータ基盤は未構築であるような状況を想定する。</p><p>また、特定システムやサービスのDB設計ではなく、組織全体で用いるデータマネジメントを対象とする。なお、データベースに格納されたテーブルデータや、CSV・JSONファイルなど、システムで保持するような構造化されたデータを主に扱う。Google Workspace・SharePoint・BOXなどに格納されたオフィス文書や画像などの非構造ファイルの扱いは、各章で明記しない限りは触れないとする。</p><p>データマネジメントの知識体系として、DAMA-DMBOK第２版（以下DMBOK2）があり、以下のような11領域の分類が有名である。</p><p><img src="'+r+'" alt=""></p><p>本ガイドラインでは上記を網羅的に説明するものでも、この分類に完全に従うものではない。主にデータ基盤やその周辺システムの構築を通して、必要なデータマネジメント方針をまとめたものである。</p><p>また、データマネジメントは特定の技術を指す用語では無いが、技術要素としてAWSを例に上げることが多い。</p><h2 id="用語定義" tabindex="-1">用語定義 <a class="header-anchor" href="#用語定義" aria-label="Permalink to &quot;用語定義&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">用語</th><th style="text-align:left;">説明</th></tr></thead><tbody><tr><td style="text-align:left;">ビジネスユーザー</td><td style="text-align:left;">データ基盤利用者のうち、業務部門のことを指す。業務の効率化、分析、調査などを行う。ITエンジニアとは限らない</td></tr><tr><td style="text-align:left;">データ資産</td><td style="text-align:left;">分析や可視化を通して業務改善や新規事業に活かせると考えられるデータ。構造データ、半構造データ、非構造データを問わない</td></tr><tr><td style="text-align:left;">構造データ</td><td style="text-align:left;">リレーショナルデータベース（RDBMS）のように、スキーマ（データの構造）をデータ書き込み時に定義・適用するデータ（Schema On Write）</td></tr><tr><td style="text-align:left;">半構造データ</td><td style="text-align:left;">オブジェクトストレージなどに保存されているCSV、JSON、Parquetなどのように、データ自体に構造情報（タグなど）を含むが、厳密なスキーマ定義は読み込み時に行われるデータ（Schema On Read）</td></tr><tr><td style="text-align:left;">非構造データ</td><td style="text-align:left;">画像・音声・動画やオフィス系のファイルを指す</td></tr><tr><td style="text-align:left;">データソース</td><td style="text-align:left;">データの発生源。本書では概ねシステム化されていることを前提とする</td></tr></tbody></table><h2 id="謝辞" tabindex="-1">謝辞 <a class="header-anchor" href="#謝辞" aria-label="Permalink to &quot;謝辞&quot;">​</a></h2><p>このアーキテクチャガイドラインの作成には多くの方々にご協力いただいた。心より感謝申し上げる。</p><ul><li><strong>作成者</strong>: 真野隼記、中神孝士、佐々木伸悟、赤倉優蔵、古谷優子</li></ul><h2 id="articles" tabindex="-1">Articles <a class="header-anchor" href="#articles" aria-label="Permalink to &quot;Articles&quot;">​</a></h2><ul><li>2025.12.29 <a href="https://future-architect.github.io/articles/20251229a/" target="_blank" rel="noreferrer">データマネジメント設計ガイドラインを公開しました</a></li></ul><div class="next-page-nav"><p>次のページ: <a href="./datamanagement_guidelines.html">データマネジメント設計ガイドライン</a></p></div>',20)])])}const u=e(n,[["render",d]]);export{g as __pageData,u as default};
